//! NekoPak native desktop client. The UI is rendered directly by Slint
//! (GPU with a CPU fallback); there is no embedded browser or WebView2.
#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

slint::include_modules!();

mod actions;
mod app;
mod auth;
#[cfg(feature = "automation")]
mod automation;
mod autostart;
mod cloud;
mod collate;
mod demo;
mod desktop;
mod files;
mod format;
mod frames;
#[cfg(windows)]
mod frames_win;
mod gallery;
// Generated by scripts/gen-native-assets.mjs; kept byte-identical to its output.
mod generated {
    #[rustfmt::skip]
    pub mod icons;
    #[rustfmt::skip]
    pub mod palettes;
}
mod host;
mod i18n;
mod media;
mod names;
mod nav;
mod overlay;
mod pages;
mod palette;
mod panel;
mod platform;
mod prefs;
mod preview;
mod settings;
mod settings_page;
mod shortcuts;
mod sync_mount;
mod tools;
mod transfers;
mod updates;
mod window_events;

use app::App;
use host::HostEvent;
use slint::ComponentHandle;
use std::rc::Rc;

fn fail(message: &str) -> ! {
    eprintln!("NekoPak could not start: {message}");
    let _ = rfd::MessageDialog::new()
        .set_title("NekoPak")
        .set_description(message)
        .set_level(rfd::MessageLevel::Error)
        .show();
    std::process::exit(1);
}

fn main() {
    let runtime = match tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
    {
        Ok(runtime) => runtime,
        Err(error) => fail(&error.to_string()),
    };
    // Providers create timers and sockets, so the host starts inside the runtime.
    let guard = runtime.enter();
    let host = match host::start() {
        Ok(host) => host,
        Err(message) => fail(&message),
    };
    let ui = match AppWindow::new() {
        Ok(ui) => ui,
        Err(error) => fail(&format!("The window could not be created: {error}")),
    };
    let (events, mut inbox) = tokio::sync::mpsc::unbounded_channel::<HostEvent>();
    if !host.mock
        && std::env::var_os("NEKOPAK_TEST_DATA_DIR").is_none()
        && !desktop::claim_single_instance(&events)
    {
        return;
    }
    host::spawn_workers(&host.service, events.clone());
    drop(guard);

    let ctx = App::new(ui, host, runtime.handle().clone());
    let translations = ctx.ui.global::<Tr>();
    translations.on_translate(|source| i18n::tr(&source).into());
    translations.on_format1(|source, a| i18n::tx(&source, &[&a]).into());
    translations.on_format2(|source, a, b| i18n::tx(&source, &[&a, &b]).into());
    overlay::install(&ctx);
    nav::install(&ctx);
    files::install(&ctx);
    panel::install(&ctx);
    transfers::install(&ctx);
    shortcuts::install(&ctx);
    palette::install(&ctx);
    preview::install(&ctx);
    gallery::install(&ctx);
    window_events::install(&ctx);
    ctx.ui.on_scheme_changed({
        let weak = Rc::downgrade(&ctx);
        move |_| {
            if let Some(ctx) = weak.upgrade() {
                settings::apply_theme(&ctx);
            }
        }
    });
    settings::apply_theme(&ctx);
    ctx.ui.global::<Shell>().on_retry_boot({
        let weak = Rc::downgrade(&ctx);
        move || {
            if let Some(ctx) = weak.upgrade() {
                let task = ctx.clone();
                task.spawn(async move { settings::boot(&ctx).await });
            }
        }
    });
    ctx.spawn({
        let ctx = ctx.clone();
        async move { settings::boot(&ctx).await }
    });
    ctx.spawn({
        let ctx = ctx.clone();
        async move {
            while let Some(event) = inbox.recv().await {
                match event {
                    HostEvent::TransfersChanged => transfers::request_reload(&ctx),
                    HostEvent::AuthChanged(event) => settings::on_auth_changed(&ctx, event),
                    HostEvent::StorageError(error) => ctx.toast_error(&error),
                    HostEvent::Quit => {
                        let _ = slint::quit_event_loop();
                    }
                    HostEvent::Activate(target) => desktop::activate(&ctx, target),
                    HostEvent::ScanProgress(event) => tools::on_scan_progress(&ctx, event),
                    HostEvent::SyncChanged(event) => tools::on_sync_changed(&ctx, event, false),
                    HostEvent::SyncPlanReady(event) => tools::on_sync_changed(&ctx, event, true),
                }
            }
        }
    });
    #[cfg(feature = "automation")]
    automation::install(&ctx);
    let tray = desktop::install_tray(&events);
    desktop::install_close_handler(&ctx, tray.is_some());
    if let Err(error) = ctx
        .ui
        .show()
        .and_then(|_| slint::run_event_loop_until_quit())
    {
        fail(&error.to_string());
    }
    let _tray = tray;
    // Leave no stale mount behind; bounded so exit never hangs on the network.
    let service = ctx.svc.clone();
    let _ = runtime.block_on(async move {
        tokio::time::timeout(std::time::Duration::from_secs(5), service.stop_all_mounts()).await
    });
    // Stop background workers without waiting on in-flight network calls.
    runtime.shutdown_background();
}
